        var range = base + '..HEAD';
        var merges = cleanCommandOutput(cmd('git rev-list --merges ' + range) || '').trim();
        if (merges) return false;
        var subjects = cleanCommandOutput(cmd('git log --format=%s ' + range) || '').split('\n')
            .map(function (l) { return l.trim(); }).filter(Boolean);
