            success: true,
            message: ticketKey + ' rework pushed, PR commented, moved to ' + statuses.IN_REVIEW,
            branchName: branchName,
            prUrl: prUrl,
            prCommentPosted: prCommentPosted
        };

    } catch (error) {
        return handleActionError(params, error, tracker);
    }
}

