    /not introduced by (?:this|the) pr/i,
    /not touched by (?:this|the) pr/i,
    /pr does not touch/i,
    /pre-?existing (?:issue|failure|violation|red)/i,
    /\b(?:classified|marked|categorized|labelled|labeled)\s+as\s+(?:a\s+|an\s+|pure\s+)?infra\b/i,
