        if (!m) return;
        taken[idx] = true;
        out.push({
            check: checkName,
            rule: m[6],
            path: m[3],
            line: parseInt(m[4], 10),
            detail: (m[1] === 'error' ? '' : '[' + m[1] + '] ') + m[2]
