/** dart test: "[optional progress prefix]path: <test name> [E]" failure lines. */
function dartTestViolations(lines, checkName, taken, out) {
    var re = /^(?:\s*\d{1,2}:\d{2}\s+\+\d+(?:\s+-\d+)*:\s*)?\s*(\S+\.dart):\s+(.+?)\s+\[E\]\s*$/;
    lines.forEach(function(line, idx) {
        if (taken[idx]) return;
        var m = line.match(re);
        if (!m) return;
        taken[idx] = true;
        out.push({
            check: checkName,
            rule: 'test',
            path: m[1],
            line: null,
            detail: m[2]
        });
