function dartAnalyzeViolations(lines, checkName, taken, out) {
    var re = /^\s*(error|warning|info)\s+•\s+(.+?)\s+•\s+(.+?):(\d+):(\d+)\s+•\s+(\S+)\s*$/;
    lines.forEach(function(line, idx) {
        if (taken[idx]) return;
        var m = line.match(re);
        if (!m) return;
        taken[idx] = true;
        out.push({
            check: checkName,
            rule: m[6],
            path: m[3],
            line: parseInt(m[4], 10),
            detail: (m[1] === 'error' ? '' : '[' + m[1] + '] ') + m[2]
        });
    });
