    // is not the rule name (thread PRT_kwDORYAuYs6uJ01M).
    var rule = String(v.rule).toLowerCase();
    var ruleRe = new RegExp('\\b' + rule.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b');
