    var path = normalizePath(v.path).toLowerCase();
    var basename = path.split('/').pop();
    return (path.length > 0 && normalizedLine.indexOf(path) !== -1) ||
        (basename.length > 3 && normalizedLine.indexOf(basename) !== -1);
